exercises.solutionCode:
function formatName(first: string, last?: string, upper = false): string {
  const full = last === undefined ? first : `${first} ${last}`;
  return upper ? full.toUpperCase() : full;
}

console.log(formatName("Ada"));
console.log(formatName("Ada", "Lovelace"));
console.log(formatName("Ada", "Lovelace", true));

