exercises.solutionCode:
type Vehicle =
  | { kind: "car"; doors: number }
  | { kind: "bike"; electric: boolean }
  | { kind: "bus"; seats: number };

function describe(vehicle: Vehicle): string {
  switch (vehicle.kind) {
    case "car":
      return `car with ${vehicle.doors} doors`;
    case "bike":
      return vehicle.electric ? "electric bike" : "bike";
    case "bus":
      return `bus for ${vehicle.seats} passengers`;
    default: {
      const unreachable: never = vehicle;
      return unreachable;
    }
  }
}

console.log(describe({ kind: "car", doors: 5 }));
console.log(describe({ kind: "bike", electric: true }));
console.log(describe({ kind: "bus", seats: 40 }));

